def sha(b): return hashlib.sha256(b).hexdigest()
def decode(b): return b.decode('utf-8-sig').replace('\r\n','\n')
def enc(text): return b'\xef\xbb\xbf'+text.replace('\r\n','\n').encode('utf-8')
def fn_bounds(text,name):
    marker=f'function {name} {{'; s=text.find(marker)
    if s<0: raise RuntimeError(f'missing {name}')
    e=text.find('\nfunction ',s+len(marker))
    if e<0:e=len(text)
    return s,e
def fn(text,name):
    s,e=fn_bounds(text,name); return text[s:e]
def replace_fn(text,name,new):
    s,e=fn_bounds(text,name); return text[:s]+new.rstrip()+"\n"+text[e:]
def rep1(text,old,new,label):
    c=text.count(old)
    if c!=1: raise RuntimeError(f'{label}: count {c}')
    return text.replace(old,new,1)

